/// Fixes finite work and deadline budgets before each provider observation.
type Limits = { Pages: int; Documents: int; Events: int; Blobs: int; ReadBytes: int64; Milliseconds: int }
/// Keeps optional complete quantities distinct from partial work and captured source rows.
type Observation = { Status: string; Bytes: Nullable<int64>; Count: Nullable<int>; Pages: int; Documents: int; Events: int; Blobs: int; ReadBytes: int64; Started: DateTimeOffset; Finished: DateTimeOffset; Rows: obj array }
let limits = { Pages = 32; Documents = 32; Events = 64; Blobs = 32; ReadBytes = 1048576L; Milliseconds = 30000 }
let cases, inputs, captures = ResizeArray<obj>(), ResizeArray<obj>(), ResizeArray<obj>()
let evidenceOptions = JsonSerializerOptions(Constants.JsonSerializerOptions, WriteIndented = true, DefaultIgnoreCondition = Serialization.JsonIgnoreCondition.Never)
/// Retains complete input, provider response and assertion evidence with explicit zeros and nulls.
let save name value = File.WriteAllText(Path.Combine(__SOURCE_DIRECTORY__, name), JsonSerializer.Serialize(value, evidenceOptions))
/// Fails immediately when a measured result disagrees with the independent fixture expectation.
let check name condition (observed: obj) =
    cases.Add(box {| Name = name; Passed = condition; Observed = observed |})
    save "assertions.json" cases
    if not condition then failwith $"FAILED: {name}"
    printfn "PASS: %s" name
/// Reads only within the shared byte budget, including Cosmos wire responses and blob payloads.
let readBytes (stream: Stream) (token: CancellationToken) cap (consumed: int64 ref) =
    use output = new MemoryStream()
    let buffer = Array.zeroCreate<byte> 1024
    let mutable ended = false
    while not ended do
        token.ThrowIfCancellationRequested()
        let count = stream.ReadAsync(buffer.AsMemory(), token).AsTask().GetAwaiter().GetResult()
        consumed.Value <- consumed.Value + int64 count
        if consumed.Value > cap then failwith "read-byte-cap"
        if count = 0 then ended <- true else output.Write(buffer, 0, count)
    output.ToArray()
/// Gives evidence a content hash independent of source identity and observation time.
