/// Creates current typed metadata and a normal path through the unchanged extracted producer helper.
let metadata label n repository ownerId organizationId size attached =
    let value = { ArtifactMetadata.Default with ArtifactId = id n; RepositoryId = repository; OwnerId = ownerId; OrganizationId = organizationId; ArtifactType = ArtifactType.Prompt; MimeType = "application/octet-stream"; Size = size; BlobPath = CurrentPaths.buildBlobPath createdAt (id n); CreatedAt = createdAt; CreatedBy = "ops1060"; WorkItemId = attached }
