/// Writes a hand-built provider envelope containing actual serialized Grace events; no hosted actor is claimed.
let persist label repository artifactId grain (values: ArtifactEvent array) =
    let doc = {| id = string artifactId; GrainType = grain; PartitionKey = string repository; State = values |}
    let wire = serialize doc
    inputs.Add(box {| Label = label; EnvelopeOrigin = "modeled provider envelope; current compiled Grace event serializer"; Wire = wire |})
    use stream = new MemoryStream(Encoding.UTF8.GetBytes wire)
    use response = source.UpsertItemStreamAsync(stream, PartitionKey(string repository)).GetAwaiter().GetResult()
    response.EnsureSuccessStatusCode() |> ignore
    save "inputs.json" inputs
/// Uploads explicit fixture content to an existing container with the actual provider API.
let upload (container: BlobContainerClient) label (value: ArtifactMetadata) (bytes: byte array) =
    inputs.Add(box {| Label = label; ArtifactId = value.ArtifactId; BlobPath = value.BlobPath; ContentBase64 = Convert.ToBase64String bytes; ContentBytes = bytes.Length; ContentSha256 = hash bytes |})
    use input = new MemoryStream(bytes)
    container.GetBlobClient(value.BlobPath).Upload(input, overwrite = true) |> ignore
    save "inputs.json" inputs
/// Observes existence independently from content length, so a missing object never becomes zero bytes.
let point label (container: BlobContainerClient) path =
    let started = DateTimeOffset.UtcNow
    use deadline = new CancellationTokenSource(limits.Milliseconds)
    let blob = container.GetBlobClient(path)
    let exists = blob.Exists(deadline.Token).Value
    let bytes = if exists then Nullable(blob.GetProperties(cancellationToken = deadline.Token).Value.ContentLength) else Nullable<int64>()
    let result = {| Label = label; Path = path; Exists = exists; Bytes = bytes; Started = started; Finished = DateTimeOffset.UtcNow |}
    captures.Add(box result)
    result
/// Enumerates existing retained state afresh, folds full snapshots and counts each scoped Artifact once.
let observeDeclarations label (container: Container) repository (cap: Limits) preCancel =
    let started = DateTimeOffset.UtcNow
    let mutable pages, documents, eventCount = 0,0,0
    let consumed, rows = ref 0L, ResizeArray<obj>()
    let projected = Dictionary<Guid,ArtifactMetadata>()
    let mutable status, quantity, count = "complete-retained-artifact-declarations", Nullable<int64>(), Nullable<int>()
    use deadline = new CancellationTokenSource(cap.Milliseconds)
    if preCancel then deadline.Cancel()
    try
        let query = QueryDefinition("SELECT * FROM c WHERE c.GrainType = @grain AND c.PartitionKey = @repo AND ARRAY_LENGTH(c.State) > 0").WithParameter("@grain","Artifact").WithParameter("@repo",string repository)
        let request = QueryRequestOptions(PartitionKey = Nullable(PartitionKey(string repository)), MaxItemCount = Nullable 2)
        use iterator = container.GetItemQueryStreamIterator(query, requestOptions = request)
        while iterator.HasMoreResults do
            deadline.Token.ThrowIfCancellationRequested()
            if pages >= cap.Pages then failwith "page-cap"
            use response = iterator.ReadNextAsync(deadline.Token).GetAwaiter().GetResult()
            response.EnsureSuccessStatusCode() |> ignore
            pages <- pages + 1
            let wire = readBytes response.Content deadline.Token cap.ReadBytes consumed |> Encoding.UTF8.GetString
            captures.Add(box {| Label = label; Page = pages; HasContinuation = iterator.HasMoreResults; Wire = wire |})
            use json = JsonDocument.Parse wire
            for doc in json.RootElement.GetProperty("Documents").EnumerateArray() do
                deadline.Token.ThrowIfCancellationRequested()
                documents <- documents + 1
                if documents > cap.Documents then failwith "document-cap"
                let events = JsonSerializer.Deserialize<ArtifactEvent array>(doc.GetProperty("State").GetRawText(), Constants.JsonSerializerOptions)
                eventCount <- eventCount + events.Length
                if eventCount > cap.Events then failwith "event-cap"
                let artifact = events |> Seq.fold (fun dto event -> ArtifactMetadata.UpdateDto event dto) ArtifactMetadata.Default
                let included = artifact.RepositoryId = repository && artifact.OwnerId = owner && artifact.OrganizationId = org
                rows.Add(box {| DocumentId = doc.GetProperty("id").GetString(); Included = included; EventCount = events.Length; Projection = artifact |})
                if included then
                    match projected.TryGetValue artifact.ArtifactId with
                    | true, existing when existing <> artifact -> failwith "conflicting-projection"
                    | _ -> projected[artifact.ArtifactId] <- artifact
        deadline.Token.ThrowIfCancellationRequested()
        quantity <- Nullable(projected.Values |> Seq.sumBy (fun artifact -> artifact.Size))
        count <- Nullable projected.Count
    with
    | :? OperationCanceledException -> status <- "incomplete-cancelled"
    | :? CosmosException as ex -> status <- $"error-cosmos-{int ex.StatusCode}"
    | ex -> status <- $"incomplete-{ex.Message}"
    let result = { Status = status; Bytes = quantity; Count = count; Pages = pages; Documents = documents; Events = eventCount; Blobs = 0; ReadBytes = consumed.Value; Started = started; Finished = DateTimeOffset.UtcNow; Rows = rows.ToArray() }
    captures.Add(box {| Label = label; Observation = result |})
    save "captures.json" captures
    result
/// Lists actual Artifact-prefix objects and downloads each payload within the same finite observation budget.
let observeBlobs label (container: BlobContainerClient) (cap: Limits) preCancel =
    let started = DateTimeOffset.UtcNow
    let mutable pages, count, total = 0,0,0L
    let consumed, rows = ref 0L, ResizeArray<obj>()
    let mutable status, quantity, completeCount = "complete-observed-artifact-prefix-objects", Nullable<int64>(), Nullable<int>()
    use deadline = new CancellationTokenSource(cap.Milliseconds)
    if preCancel then deadline.Cancel()
    try
        let pagesSource = container.GetBlobsAsync(Azure.Storage.Blobs.Models.BlobTraits.None, Azure.Storage.Blobs.Models.BlobStates.None, "grace-artifacts/", deadline.Token).AsPages(pageSizeHint = Nullable 2)
        let iterator = pagesSource.GetAsyncEnumerator(deadline.Token)
        try
            let mutable more = true
            while more do
                deadline.Token.ThrowIfCancellationRequested()
                if pages >= cap.Pages then failwith "page-cap"
                more <- iterator.MoveNextAsync().AsTask().GetAwaiter().GetResult()
                if more then
                    pages <- pages + 1
                    let page = iterator.Current
                    for blob in page.Values do
                        deadline.Token.ThrowIfCancellationRequested()
                        count <- count + 1
                        if count > cap.Blobs then failwith "blob-cap"
                        let response = container.GetBlobClient(blob.Name).DownloadStreaming(cancellationToken = deadline.Token)
                        use stream = response.Value.Content
                        let bytes = readBytes stream deadline.Token cap.ReadBytes consumed
                        total <- total + int64 bytes.LongLength
                        if blob.Properties.ContentLength <> Nullable(int64 bytes.LongLength) then failwith "length-changed"
                        rows.Add(box {| Path = blob.Name; ListedBytes = blob.Properties.ContentLength; ObservedBytes = bytes.LongLength; Exists = true; ContentBase64 = Convert.ToBase64String bytes; ContentSha256 = hash bytes |})
                    captures.Add(box {| Label = label; Page = pages; HasContinuation = not(String.IsNullOrEmpty page.ContinuationToken); BlobRows = rows.ToArray() |})
                    if String.IsNullOrEmpty page.ContinuationToken then more <- false
            deadline.Token.ThrowIfCancellationRequested()
            quantity <- Nullable total
            completeCount <- Nullable count
        finally iterator.DisposeAsync().AsTask().GetAwaiter().GetResult()
    with
    | :? OperationCanceledException -> status <- "incomplete-cancelled"
    | :? RequestFailedException as ex -> status <- $"error-blob-{ex.Status}"
    | ex -> status <- $"incomplete-{ex.Message}"
    let result = { Status = status; Bytes = quantity; Count = completeCount; Pages = pages; Documents = 0; Events = 0; Blobs = count; ReadBytes = consumed.Value; Started = started; Finished = DateTimeOffset.UtcNow; Rows = rows.ToArray() }
    captures.Add(box {| Label = label; Observation = result |})
    save "captures.json" captures
    result
