#Requires -Version 7.6
param([Parameter(Mandatory)][string] $EvidencePath, [Parameter(Mandatory)][string] $Destination)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
if (Test-Path -LiteralPath $Destination) { throw 'Extraction requires a new, absent directory; preserve any previous replay.' }
$evidence = Get-Content -LiteralPath $EvidencePath -Raw | ConvertFrom-Json -Depth 100
$resolvedDestination = [IO.Path]::GetFullPath($Destination)
New-Item -ItemType Directory -Path $resolvedDestination | Out-Null
foreach ($source in $evidence.ExecutableSources) {
    if ([IO.Path]::GetFileName($source.Name) -cne $source.Name) { throw 'Executable source name must be a single filename.' }
    $bytes = [Convert]::FromBase64String($source.ContentBase64)
    $actualHash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($bytes)).ToLowerInvariant()
    if ($actualHash -cne $source.Sha256) { throw "Captured source hash mismatch: $($source.Name)" }
    [IO.File]::WriteAllBytes((Join-Path $resolvedDestination $source.Name), $bytes)
}
Write-Output "Extracted and verified $($evidence.ExecutableSources.Count) complete executable sources to $resolvedDestination"
